entries[1229205] = { ["name"] = "Sands of K'aresh", ["text"] = "When Brann uses Gathering Tools , sands begin swirling around party members, granting 6% Critical Strike up to 10 times and slowing nearby enemies by 6%.\n\nDealing a Critical Strike creates a Sand Devil at the target's location for 6 sec that periodically pulls enemies to its center. Can only occur every 45 sec.\n\nGathering Tools\nBrann uses his gathering tools to help players find additional gold, ore, herbs, fish, leathers, and treasures." }
entries[1229206] = { ["name"] = "Sands of K'aresh", ["text"] = "When Brann uses Gathering Tools , sands begin swirling around party members, granting 8 % Critical Strike up to 10 times and slowing nearby enemies by 8 %.\n\nDealing a Critical Strike creates a Sand Devil at the target's location for 6 sec that periodically pulls enemies to its center. Can only occur every 45 sec.\n\nGathering Tools\nBrann uses his gathering tools to help players find additional gold, ore, herbs, fish, leathers, and treasures." }
