entries[1229208] = { ["name"] = "Sands of K'aresh", ["text"] = "When Brann uses Gathering Tools , sands begin swirling around party members, granting 12 % Critical Strike up to 10 times and slowing nearby enemies by 12 %.\n\nDealing a Critical Strike creates a Sand Devil at the target's location for 6 sec that periodically pulls enemies to its center. Can only occur every 45 sec.\n\nGathering Tools\nBrann uses his gathering tools to help players find additional gold, ore, herbs, fish, leathers, and treasures." }
entries[1229209] = { ["name"] = "Temporal Decelerator Crystal", ["text"] = "Damaging an Elite at 80% or above and at 20% or below health causes Brann to trigger the crystal's energies, reducing the Elite's attack and cast speed by 20% for 30 sec. Killing the targeted Elite while the debuff is active grants the party an 2% stacking Haste buff." }
