entries[1229213] = { ["name"] = "Battered Aegis", ["text"] = "While the Aegis is equipped, all party members deal 3 % increased damage and healing. Every 10 sec during combat, you and Brann heal for 5 % of the damage you've taken during that time.\n\nWhen a player dies, the Aegis grants them 1 % damage reduction and 2 % increased healing received upon revival, but reduces their damage and healing dealt by 1 % stacking up to 3 times." }
