entries[1229916] = { ["name"] = "Lucky Keychain", ["text"] = "2 sec cast\nTools: Arclight Spanner , Gyromatic Micro-Adjustor\nReagents:\nPile of Junk (10), Mote of Wild Magic , Evercore (5)\nOptional Reagents:\nProfession:\nRecycling\n\nLucky Keychain\nOptional Crafting Reagent\n\nProvides the following property:\n\nGrants your equipment +1 Sparkle.\nUsable with: Midnight recipes for most unembellished equipment.\n\"Can be bought and sold on the Auction House.\"" }
entries[1229917] = { ["name"] = "M3DDY, Travel-Sized", ["text"] = "2 sec cast\nTools: Arclight Spanner , Gyromatic Micro-Adjustor\nReagents:\nSoul Sprocket , Aetherlume (3), Evercore (2)\nOptional Reagents:\nProfession:\nRecycling\n\nM3DDY, Travel-Sized\nOptional Crafting Reagent\n\nProvides the following property:\n\nA pocket-sized version of your buddy, M3DDY, that will revive you upon your untimely demise while outdoors.\nUsable with: Midnight recipes for most unembellished equipment.\n\"Created by players with the Engineering skill. Can be bought and sold on the Auction House.\"" }
entries[1229919] = { ["name"] = "Kinetic Ankle Primers", ["text"] = "2 sec cast\nTools: Arclight Spanner , Gyromatic Micro-Adjustor\nReagents:\nSong Gear (2), Aetherlume (3), Evercore\nOptional Reagents:\nProfession:\nRecycling\n\nKinetic Ankle Primers\nOptional Crafting Reagent\n+15 Recipe Difficulty\nProvides the following property: Prime your boots for engagement, launching you into the air and knocking up enemies on impact.\n\nCan only be used outdoors.\nUsable with: Midnight Engineering Boots\n\"Can be bought and sold on the Auction House.\"" }
entries[1229921] = { ["name"] = "HU5H, Nonchalant Pup", ["text"] = "2 sec cast\nTools: Arclight Spanner , Gyromatic Micro-Adjustor\nReagents:\nPile of Junk (10), Mote of Pure Void , Evercore (5)\nOptional Reagents:\nSpecialization:\nBits and Bots - Bots (30)\n\nHU5H, Nonchalant Pup\nOptional Crafting Reagent\n+15 Recipe Difficulty\nProvides the following property: Grants the user invisibility for 4-18 sec.\n\nCan only be used outdoors. Cannot be cast in combat.\nUsable with: Midnight Engineering Crafted Equipment\n\"Can be bought and sold on the Auction House.\"" }
entries[1229922] = { ["name"] = "B1P, Scorcher of Souls", ["text"] = "2 sec cast\nTools: Arclight Spanner , Gyromatic Micro-Adjustor\nReagents:\nPile of Junk (10), Mote of Wild Magic , Evercore (5)\nOptional Reagents:\nProfession:\nRecycling\n\nB1P, Scorcher of Souls\nOptional Crafting Reagent\n+15 Recipe Difficulty\nProvides the following property: Summons B1P, Scorcher of Souls to spray soul sparks on your enemies dealing Fire damage in a cone in front of you for 6 sec.\nUsable with: Midnight Engineering Crafted Equipment\n\"Summons Bip, Soul Scorcher. Created by players with the Engineering skill. Can be bought and sold on the Auction House.\"" }
entries[1229923] = { ["name"] = "Emergency Soul Link", ["text"] = "2 sec cast\nTools: Arclight Spanner , Gyromatic Micro-Adjustor\nReagents:\nSoul Sprocket , Evercore\nOptional Reagents:\nProfession:\nRecycling\n\nEmergency Soul Link\n\nUse: Convince a dead ally that being alive is much more fun by catalyzing your whimsy, restoring them to life with 35% health and 10% mana. This always succeeds because it's objective truth.\n\nCastable in combat. Item quality affects cast time. Cannot be used by players higher than level 90. (10 Min Cooldown)\n68" }
entries[1229924] = { ["name"] = "M3DDY", ["text"] = "2 sec cast\nTools: Arclight Spanner , Gyromatic Micro-Adjustor\nReagents:\nSong Gear , Soul Sprocket , Evercore\nOptional Reagents:\nSpecialization:\nBits and Bots - Bots\n\nM3DDY\n\nUse: Upon your untimely demise, summon M3DDY to... medicalize you and your raid back to life!\n\nDoes not work on players whose spirits have been released and are above level 90.\n81" }
entries[1229926] = { ["name"] = "W-47CH D0G", ["text"] = "2 sec cast\nTools: Arclight Spanner , Gyromatic Micro-Adjustor\nReagents:\nPile of Junk (3), Song Gear , Evercore\nOptional Reagents:\nProfession:\nRecycling\n\nUse: Deploy a W-47CH D0G unit that will calm the nerves of nearby party members, halting the expiration of Thalassian Flasks, Phials, and Well Fed effects.\n\nThe pylon is extremely fragile and will detonate in the presence of violence.\n78" }
entries[1229927] = { ["name"] = "Curious Red Button", ["text"] = "2 sec cast\nTools: Arclight Spanner , Gyromatic Micro-Adjustor\nReagents:\nPile of Junk (3), Song Gear , Evercore\nOptional Reagents:\nResourcefulness (#496)\nProfession:\nRecycling\n\nCurious Red Button\n\nUse: Deploy a particularly curious device.\n\nLasts for 10 min. Must be deployed prior to combat. Only usable outdoors. (10 Min Cooldown)\n78" }
entries[1229928] = { ["name"] = "Wormhole Generator: Quel'Thalas", ["text"] = "2 sec cast\nTools: Arclight Spanner , Gyromatic Micro-Adjustor\nReagents:\nPile of Junk (3), Song Gear , Evercore\nOptional Reagents:\nResourcefulness (#496)\nProfession:\nRecycling\n\nWormhole Generator: Quel'Thalas\nToy\n\nUse: Open a wormhole that allows the user to quickly travel to a random Midnight location. (30 Min Cooldown)\n78\nRequires Midnight Engineering\n(1)" }
entries[1229930] = { ["name"] = "Recycling", ["text"] = "2 sec cast\nTools: Arclight Spanner , Gyromatic Micro-Adjustor\nRecycle 5 crafted reagents from a variety of Midnight Professions to salvage necessary components like Aetherlume and Evercores.\n\nSpecializing in Recycling can learn new recipes!\n\n[][ Recycling has a chance to learn new recipes. ]Profession:\nEngineering (1)Profession Trainer:\nMidnight Engineering (15)\nCost:\n100" }
