entries[1230050] = { ["name"] = "Vantus Rune: Radiant", ["text"] = "3.5 sec cast\nReagents:\nThalassian Songwater , Lexicologist's Vellum , Petrified Root (2), Soul Cipher\nOptional Reagents:\nProfession Trainer:\nMidnight Inscription (50)\nCost:\n270\n\nVantus Rune: Radiant\n\nUse: Once per week, attune yourself to the energies of the targeted March on Quel'Danas, The Dreamrift, The Voidspire, and Sporefall raid bosses and gain the following aura:\n\nVantus Rune: Radiant\nIncrease your Versatility by 259 when fighting the targeted raid boss. This effect lasts the entire week.\n70" }
entries[1230051] = { ["name"] = "Contract: The Silvermoon Court", ["text"] = "3.5 sec cast\nReagents:\nLexicologist's Vellum , Mote of Wild Magic (3), Munsell Ink , Sienna Ink\nOptional Reagents:\nVendor:\nCaeris Fairdawn\nZone:\nEversong Woods\nCost:\n150\n1500\n\nContract: The Silvermoon Court\n\nUse: Sign a contract that allows you to gain 10 reputation with The Silvermoon Court every time you complete a world quest in Midnight zones.\n\nWarband Contract\nYou may only sign one contract per week. This effect is shared across your Warband.\n70\n\"A document drafted by Scribes pledging a Warband's allegiance to a faction.\"" }
