entries[1230070] = { ["name"] = "Darkmoon Dominion: Blood", ["text"] = "2 sec cast 3\nReagents:\nThalassian Songwater , Mote of Light (20), Darkmoon Deck: Blood , Tormented Tantalum , Codified Azeroot (10), Soul Cipher (5), Spark (#500) (2)\nOptional Reagents:\nSpecialization:\nDarkmoon Curiosity - Darkmoon Dominion: Blood\n\nDarkmoon Dominion: Blood\nBinds when picked up\nUnique-Equipped\nUnique-Equipped: Darkmoon Deck (1)Trinket\n+6 [Agility or Strength or Intellect] Equip: Your damaging spells and abilities have the chance to grant Farstrider's Guile , increasing your lowest secondary stat by 31 for 15 sec.\n\nWhen an allied player dies, gain 4 of your highest secondary stat for 15 sec. This effect can only occur once every 5 min.\n\nThis effect is augmented by Darkmoon Sigil: Blood." }
entries[1230071] = { ["name"] = "Darkmoon Dominion: Rot", ["text"] = "2 sec cast 3\nReagents:\nThalassian Songwater , Mote of Primal Energy (20), Darkmoon Deck: Rot , Tormented Tantalum , Codified Azeroot (10), Soul Cipher (5), Spark (#500) (2)\nOptional Reagents:\nSpecialization:\nDarkmoon Curiosity - Darkmoon Dominion: Rot\n\nDarkmoon Dominion: Rot\nBinds when picked up\nUnique-Equipped\nUnique-Equipped: Darkmoon Deck (1)Trinket\n+6 [Agility or Strength or Intellect] Equip: Afflict your target with Rotting Roots dealing 3 Nature Damage every 2 seconds for 6 sec. This effect stacks up to 10 times. New stacks do not refresh applied stacks.\n\nThis effect is augmented by Darkmoon Sigil: Rot." }
entries[1230072] = { ["name"] = "Darkmoon Dominion: Hunt", ["text"] = "2 sec cast 3\nReagents:\nThalassian Songwater , Mote of Wild Magic (20), Darkmoon Deck: Hunt , Tormented Tantalum , Codified Azeroot (10), Soul Cipher (5), Spark (#500) (2)\nOptional Reagents:\nSpecialization:\nDarkmoon Curiosity - Darkmoon Dominion: Hunt\n\nDarkmoon Dominion: Hunt\nBinds when picked up\nUnique-Equipped\nUnique-Equipped: Darkmoon Deck (1)Trinket\n+6 [Agility or Strength or Intellect] Equip: Your spells and abilities have the chance to grant 12 secondary stats for 15 sec based on the target creature's type.\n\nThis effect is augmented by Darkmoon Sigil: Hunt." }
entries[1230073] = { ["name"] = "Darkmoon Dominion: Void", ["text"] = "2 sec cast 3\nReagents:\nThalassian Songwater , Mote of Pure Void (20), Darkmoon Deck: Void , Tormented Tantalum , Codified Azeroot (10), Soul Cipher (5), Spark (#500) (2)\nOptional Reagents:\nSpecialization:\nDarkmoon Curiosity - Darkmoon Dominion: Void\n\nDarkmoon Dominion: Void\nBinds when picked up\nUnique-Equipped\nUnique-Equipped: Darkmoon Deck (1)Trinket\n+6 [Agility or Strength or Intellect] Equip: Your damaging spells and abilities have the chance to embolden you in Void Glass granting 9 Versatility over 15 sec. Multiple applications can overlap.\n\nThis effect is augmented by Darkmoon Sigil: Void." }
entries[1230074] = { ["name"] = "Darkmoon Sigil: Blood", ["text"] = "2 sec cast 2\nReagents:\nThalassian Songwater , Mote of Light (10), Darkmoon Deck: Blood , Soul Cipher (5)\nOptional Reagents:\nSpecialization:\nDarkmoon Curiosity - Darkmoon Sigil: Blood\n\nDarkmoon Sigil: Blood\nOptional Crafting Reagent\n+15 Recipe Difficulty\nProvides the following property: Your damaging spells and abilities have the chance to grant Farstrider's Guile , increasing your lowest secondary stat by 76 for 15 sec.\n\nWhen an allied player dies, gain 63 of your highest secondary stat for 15 sec. This effect can only occur once every 5 min.\n\nUnique-Equipped: Embellished 2.\nUsable with: Midnight recipes for most unembellished weapons and off-hands.\n\"Can be bought and sold on the Auction House.\"" }
entries[1230075] = { ["name"] = "Darkmoon Sigil: Rot", ["text"] = "2 sec cast 2\nReagents:\nThalassian Songwater , Mote of Primal Energy (10), Darkmoon Deck: Rot , Soul Cipher (5)\nOptional Reagents:\nSpecialization:\nDarkmoon Curiosity - Darkmoon Sigil: Rot\n\nDarkmoon Sigil: Rot\nOptional Crafting Reagent\n+15 Recipe Difficulty\nProvides the following property: Afflict your target with Rotting Roots dealing 113 Nature Damage every 2 seconds for 6 sec. This effect stacks up to 10 times. New stacks do not refresh applied stacks.\n\nUnique-Equipped: Embellished 2.\nUsable with: Midnight recipes for most unembellished weapons and off-hands.\n\"Can be bought and sold on the Auction House.\"" }
